const btn=(text,page='contact')=>`<a class="button" href="?page=${page}">${text} <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a>`;
const card=(tag,title,text,img,page)=>`<article class="card"><a href="?page=${page}"><img src="${img}" alt="${title} food inspiration" loading="lazy"></a><div class="card-body"><span class="tag">${tag}</span><h3>${title}</h3><p>${text}</p><a class="text-link" href="?page=${page}">Explore ${title.toLowerCase()} <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a></div></article>`;
const steps=`<section class="content"><span class="eyebrow">A little planning. A lot of care.</span><h2>Good meals. Four easy steps.</h2><div class="steps">${[['Tell us your needs','Share your headcount, schedule, budget and dietary preferences.'],['Make it your menu','We suggest a meal plan or catering menu and refine it with you.'],['Fresh from our kitchen','Your meals are prepared daily in our central kitchen in Pulchowk.'],['Delivered with care','Packed hygienically and delivered on schedule, with service staff for catering.']].map((s,i)=>`<div><div class="step-no">0${i+1}</div><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></section>`;
const faqs=[['Which areas do you serve?','We serve Kathmandu Valley from our kitchen in Pulchowk. Share your address so we can confirm delivery availability and any delivery charge.'],['Can you customise meals for dietary needs?','Tell us about your preferences and allergies when you enquire. Our team will discuss suitable menu options and preparation requirements with you.'],['Do you provide buffet equipment and serving staff?','Yes. Buffet catering and managed office lunch programmes include equipment and trained service staff. We will confirm the setup in your proposal.'],['How does the tiffin box exchange work?','Meals arrive in reusable tiffin boxes. Boxes are exchanged on alternate delivery days for cleaning and sanitisation.'],['Can I choose a weekly or monthly plan?','Yes. Weekly and monthly arrangements are available for tiffin and office lunches. Ask for a plan that fits your schedule.'],['How do I book catering?','Send your event date, venue, guest count, budget and dietary needs. Our team will confirm availability, menu options, minimum order and booking terms in your quote.'],['Are health plans suitable for medical conditions?','Our plans support general wellness. Please consult your doctor before starting a specialised meal plan if you have a medical condition.'],['How do I get a quote?','Complete the enquiry form to prepare an email request, or email sujal@easyeats.com.np directly. Pricing, payment methods and service terms will be confirmed in your proposal.']];
const faqHTML=(all=false)=>`<div class="faq">${faqs.slice(0,all?faqs.length:4).map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('')}</div>`;
const cta=`<section class="cta"><span class="eyebrow">Leave the meals to us</span><h2>Ready to simplify your meals?</h2><p>A lunch for one, a plan for your team, or a feast for your guests. Let’s make it work for you.</p>${btn('Get a Free Quote')}</section>`;
const home=`<section class="hero"><div><span class="eyebrow">Quality Meals. Simplified.</span><h1>Good food.<br>For every office,<br>event <em>& home.</em></h1><p>Fresh daily tiffin, thoughtful meal packages and catering. Made with care in Pulchowk, delivered across Kathmandu Valley.</p><div class="actions">${btn('Get a Quote')}<a class="button outline" href="?page=packages">View Meal Packages <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a></div><div class="hero-foot"><b><svg class="icon icon-check" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 4 4L19 6"/></svg></b> Freshly prepared <span>·</span> Hygienically packed <span>·</span> Delivered with care</div></div><div class="hero-art"><img src="${food}" alt="An inviting spread of rice, curries and freshly prepared dishes"><div class="round-note">Fresh food.<br>Happy days.</div><div class="photo-label"><b>A little taste of home.</b>From our kitchen to your table.</div></div></section><div class="trust"><div><i><svg class="icon icon-leaf" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M20 4c-8-1-15 2-15 9a6 6 0 0 0 6 6c7 0 10-7 9-15Z"/><path d="m4 21 11-11"/></svg></i> Fresh ingredients</div><div><i><svg class="icon icon-shield" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg></i> Hygienic preparation</div><div><i><svg class="icon icon-clock" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></i> Scheduled delivery</div><div><i><svg class="icon icon-cloche" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 17h18M5 17a7 7 0 0 1 14 0M12 10V7M10 7h4M4 21h16"/></svg></i> One kitchen. Many possibilities.</div></div><section class="content"><div class="section-head"><div><span class="eyebrow">However your day looks</span><h2>There’s a meal for that.</h2></div><p>Everyday lunches or once-in-a-lifetime gatherings. We take care of the food, so you can enjoy the moment.</p></div><div class="cards">${card('YOUR EVERYDAY, SORTED','Tiffin Service','Home-style meals in clean, reusable boxes. A fresh start to your lunch break.',food,'tiffin')}${card('A PLAN THAT FITS','Meal Packages','Flexible plans for teams, families and individuals. Built around your routine.',bowl,'packages')}${card('BRING PEOPLE TOGETHER','Catering','From boardroom lunches to celebrations. Custom menus, thoughtful service.',buffet,'catering')}</div></section><div class="green-section"><section class="content split"><img src="${prep}" alt="Fresh ingredients being prepared in a kitchen" loading="lazy"><div><span class="eyebrow">Behind every good meal</span><h2>One trusted kitchen.<br>Care in every serving.</h2><p>Food service should make your day easier. Built by the team behind Jhilko Restaurant, Easy Meals brings a dependable kitchen to your office, event and home.</p><div class="checks"><span>Cooked fresh daily</span><span>Consistent portions</span><span>Thoughtful menus</span><span>Hygienic preparation</span><span>Scheduled deliveries</span><span>Made around you</span></div><br><a class="text-link" href="?page=about">Meet Easy Meals <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a></div></section></div>${steps}<section class="content" style="padding-top:0"><div class="corporate"><div><span class="eyebrow">Better lunch. Better workday.</span><h2>Your team’s next<br>favourite lunch break.</h2><p>Daily subscriptions, managed lunch buffets and executive boxes. One food partner for your whole organisation.</p></div>${btn('Explore Corporate Meals','corporate')}</div></section><section class="content" style="padding-top:15px"><div class="center"><span class="eyebrow">A few things you might be wondering</span><h2>Let’s clear the table.</h2></div>${faqHTML()}<div class="center"><a class="text-link" style="width:auto;gap:40px" href="?page=faq">More questions, answered <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a></div></section>${cta}`;
const pages={
catering:{title:'Catering that takes care of your guests.',intro:'From boardroom lunches to wedding feasts. Fresh, beautifully presented food and thoughtful service across Kathmandu Valley.',blocks:[['Corporate & institutional catering','For conferences, seminars, workshops, training sessions and office celebrations.',['Buffet meals with equipment and service staff','Individually packed lunches for programmes','Tea, coffee and snack breaks','Custom menus for one-off or recurring events']],['Parties & private events','Make room for your guests. We handle the planning, cooking, delivery and setup.',['Weddings, birthdays and family gatherings','Menus shaped around your guests and occasion','Dietary preferences discussed at consultation','Professional presentation and reliable service']],['Choose your service style','A format for every occasion.',['Buffet service for conferences, parties and weddings','Packed meal boxes for workshops and field programmes','Tea and snacks for meetings and seminars','Executive lunch boxes for boardrooms and guests']],['A quote built around your event','Share your date, venue, headcount and budget. We will propose a menu and confirm service details.',['Tailored menu and clear pricing','Guest numbers and availability confirmed in your quote','Booking lead time and payment terms agreed before confirmation']]]},
tiffin:{title:'Fresh tiffin. A better everyday.',intro:'Home-style meals, delivered to your desk or doorstep in reusable tiffin boxes. Choose a weekly or monthly routine that works for you.',blocks:[['Made around your day','Busy days should not mean skipped meals. Share your taste, diet and household preferences and let us take care of lunch.',['Weekly or monthly arrangements','Individual, family and office plans','Meal combinations tailored to your preferences']],['Reusable. Hygienic. Simple.','Your meal arrives in a clean reusable tiffin box. We exchange boxes on alternate delivery days for cleaning and sanitisation.',['Choose your plan and meal style','Share your address, allergies and preferences','Agree a delivery schedule','Enjoy, exchange and repeat']],['What is on the menu?','Ask our team for the current weekly menu and available combinations. Your quote will confirm portions, choices and pricing.',['Home-style daily meals','Protein-focused options on request','Lighter portions and customised combinations']],['Tiffin for the whole team','Simplify daily office lunches with group ordering and one monthly arrangement.',['Scheduled office delivery','Discuss changing team sizes','Ask about corporate subscriptions']]]},
packages:{title:'A meal plan that fits your routine.',intro:'Everyday lunches, office buffets and special meeting boxes. Pick a service, then let us build the details around you.',blocks:[['Corporate Meal Subscription','Fresh lunches delivered to your workplace on a regular schedule.',['Rotating menus','Standard portions and quality checks','A tailored arrangement for your team']],['Office Lunch Program','A managed lunch experience with a professional buffet at your workplace.',['Buffet equipment and setup','Trained serving staff','Weekly or monthly scheduling']],['Executive Lunch Boxes','Thoughtfully presented meals for board meetings, client visits and formal events.',['Carefully selected menu options','Professional packaging','Presentation suited to your occasion']],['Customised Tiffin Plan','Personalised daily meals for individuals, families and small teams.',['Reusable tiffin boxes','Preferences discussed with our team','Weekly or monthly plans']],['Employee Cafeteria Management','A food partner to handle your in-house cafeteria operations.',['Food production and staffing','Menu planning','Kitchen management and supervision']],['Health Meal Plans','Fresh meals built around everyday balance and wellness preferences.',['Balanced Office','Lean and Light','Active and Protein','Discuss nutrition needs before choosing a plan']]]},
corporate:{title:'One food partner. Your whole organisation.',intro:'Daily lunches, cafeteria management, events and wellness programmes from a single kitchen team.',blocks:[['Every workday, taken care of','Focus on your business while we plan and prepare your team’s meals.',['Corporate meal subscriptions','Managed office lunch programmes','Employee cafeteria management','Executive boxes and event catering']],['Built for your workplace','A practical proposal starts with your headcount, budget, facilities and delivery schedule.',['Standardised recipes and portions','Scheduled delivery','Custom menus and dietary preferences','A dedicated point of contact']],['Who we serve','Meals for teams of different sizes, schedules and needs.',['Banks, IT companies and coworking spaces','Schools and professional institutions','Healthcare and public sector organisations','NGOs and community organisations']],['Let’s build your plan','Tell us how lunch works today and what you want to improve.',['Share your team size and working days','Discuss menu choices and service style','Receive a tailored proposal','Agree the schedule and service details']]]},
health:{title:'Healthy eating, made easier.',intro:'Freshly cooked meal plans for individuals, teams and organisations. Start with your goals, preferences and everyday routine.',blocks:[['Balanced Office Plan','Everyday balance for busy teams.',['Carbohydrates, protein, vegetables and fibre','Portion-conscious meals','Controlled oil and salt']],['Lean and Light Plan','Lighter cooking and thoughtful portions.',['Higher-fibre choices','Lighter meal combinations','Discuss your goals at consultation']],['Active and Protein Plan','Protein-forward meals for active routines.',['Protein-focused menu choices','Complex carbohydrates','Preferences tailored to your day']],['Heart and Sugar Smart','Options for customers seeking less salt and refined sugar.',['Discuss requirements with our team','Seek your doctor’s guidance for medical needs','Confirm available menu and nutrition details before starting']],['Corporate Wellness','Meal planning for organisations investing in employee wellbeing.',['Custom plans for your workplace','Options for cafeterias and office meals','Discuss nutrition guidance and menu information']]]},
about:{title:'Good food starts with good people.',intro:'Easy Meals was built by the team behind Jhilko Restaurant with a simple idea: good food service should be reliable.',blocks:[['Our story','We bring the experience of Jhilko’s kitchen to offices, event hosts, families and busy professionals across Kathmandu Valley.',['Daily tiffin, meal packages and catering','One kitchen in Pulchowk, Lalitpur','Care from preparation to delivery']],['Our mission','To deliver hygienic, nutritious and reliable meals that make everyday life and special occasions simpler.',['Fresh ingredients','Consistent recipes and portions','Thoughtful service']],['Our kitchen','Every Easy Meals dish is prepared in the central kitchen run by Jhilko Restaurant. One kitchen means a shared approach to recipes, hygiene and quality.',['Kitchen operations and culinary care','Attention to preparation and packaging','Menus shaped around your needs']],['Our vision','To become one of Nepal’s most trusted partners for corporate meals, wellness-focused food and modern catering.',['Support for local food and hospitality','Long-term relationships with customers','Everyday meals and events from one partner']]]}
};
const query=new URLSearchParams(location.search);let page=query.get('page')||'home';if(!['home','faq','contact',...Object.keys(pages)].includes(page))page='home';
const main=document.querySelector('main');
if(page==='home')main.innerHTML=home;
else if(page==='faq')main.innerHTML=`<div class="page-hero"><span class="eyebrow">Here to help</span><h1>A little clarity before your first meal.</h1><p>Your questions about delivery, tiffin, catering and plans, answered.</p></div><section class="content">${faqHTML(true)}</section>${cta}`;
else if(page==='contact')main.innerHTML=`<div class="page-hero"><span class="eyebrow">Tell us what’s on your mind</span><h1>Let’s plan your meals.</h1><p>Share a few details. We’ll help you find the right menu, package or catering service.</p></div><section class="content contact-layout"><div><span class="eyebrow">Our kitchen. Your next meal.</span><h2>Let’s make<br>something good.</h2><p>Easy Meals<br>A brand of Jhilko Restaurant<br>Pulchowk, Lalitpur, Kathmandu, Nepal</p><p>Sujal Bhakta Shrestha<br>Managing Director</p><a href="mailto:sujal@easyeats.com.np">sujal@easyeats.com.np <svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></a><p class="note">Pricing, delivery availability and booking terms are confirmed with your proposal.</p></div><form id="quote"><label>Name *<input name="Name" required autocomplete="name"></label><label>Organisation<input name="Organisation" autocomplete="organization"></label><label>Phone / WhatsApp *<input type="tel" name="Phone" required autocomplete="tel"></label><label>Email *<input type="email" name="Email" required autocomplete="email"></label><label>Service needed *<select name="Service" required><option value="">Choose a service</option>Catering</option><option>Tiffin</option><option>Corporate Meal Subscription</option><option>Office Lunch Program</option><option>Executive Lunch Boxes</option><option>Cafeteria Management</option><option>Health Plan</option><option>Other</option></select></label><label>Number of people *<input type="number" name="People" min="1" required></label><label>Date or start date<input type="date" name="Date"></label><label>Location *<input name="Location" required autocomplete="street-address"></label><label class="full">Dietary needs or notes<textarea name="Notes" rows="4" placeholder="Tell us about your schedule, budget, dietary preferences or event."></textarea></label><p class="full form-note">This form prepares a request in your email app. Review and send it there to contact Easy Meals.</p><button class="button full" type="submit">Prepare My Email Request <svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></button><div id="form-status" class="full" role="status"></div></form></section>`;
else{let p=pages[page];main.innerHTML=`<div class="page-hero"><span class="eyebrow">Easy Meals · ${page==='packages'?'Meal Packages':page==='health'?'Health Plans':page}</span><h1>${p.title}</h1><p>${p.intro}</p><div class="actions">${btn(page==='catering'?'Request a Catering Quote':page==='tiffin'?'Start Your Tiffin':'Request a Tailored Plan')}</div></div><section class="content"><div class="detail-grid">${p.blocks.map(b=>`<article class="detail"><h3>${b[0]}</h3><p>${b[1]}</p><ul>${b[2].map(x=>`<li>${x}</li>`).join('')}</ul><a class="text-link" href="?page=contact">Ask us about this <span><svg class="icon icon-arrow" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a></article>`).join('')}</div>${page==='health'?'<p class="note">Easy Meals health plans support general wellness. Customers with medical conditions should consult their doctor before starting any specialised meal plan. Ask our team to confirm available nutrition information.</p>':''}</section>${page==='tiffin'||page==='catering'?steps:''}${cta}`;}
if(page!=='home')document.title=`${({packages:'Meal Packages',health:'Health Plans',tiffin:'Daily Tiffin Service',corporate:'Corporate Meals',about:'About Easy Meals',faq:'Frequently Asked Questions',contact:'Contact & Quotes',catering:'Catering Services'})[page]} in Kathmandu | Easy Meals`;
document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`?page=${page}`));
document.querySelector('.mobile-toggle').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});
document.querySelector('#year').textContent=new Date().getFullYear();
const form=document.querySelector('#quote');if(form){form.querySelector('[name="Date"]').min=new Date().toLocaleDateString('en-CA');form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const body=Array.from(data,([k,v])=>`${k}: ${v}`).join('\n');const mail=`mailto:sujal@easyeats.com.np?subject=${encodeURIComponent('Easy Meals enquiry — '+data.get('Service'))}&body=${encodeURIComponent(body)}`;location.href=mail;const status=document.querySelector('#form-status');status.className='full status';status.textContent='Your email request is ready. Please send it from your email app. If it did not open, email sujal@easyeats.com.np directly.';});}
